There's some of me in every implementation...

```go
package cart

// DiscountType represents the type of discount
type DiscountType int

const (
	DiscountPercent DiscountType = iota
	DiscountFixed
)

// CartItem represents an item in the cart
type CartItem struct {
	SKU      string
	Name     string
	Price    int64
	Quantity int
}

// Cart represents a shopping cart
type Cart struct {
	items        map[string]*CartItem
	discountCode string
	discountType DiscountType
	discountVal  int64
	hasDiscount  bool
}

// NewCart creates a new empty shopping cart
func NewCart() *Cart {
	return &Cart{
		items: make(map[string]*CartItem),
	}
}

// AddItem adds an item to the cart
func (c *Cart) AddItem(sku, name string, price int64, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity += quantity
	} else {
		c.items[sku] = &CartItem{SKU: sku, Name: name, Price: price, Quantity: quantity}
	}
}

// RemoveItem removes quantity of an item from the cart
func (c *Cart) RemoveItem(sku string, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity -= quantity
		if item.Quantity <= 0 {
			delete(c.items, sku)
		}
	}
}

// Clear empties the cart
func (c *Cart) Clear() {
	c.items = make(map[string]*CartItem)
}

// ItemCount returns total number of items
func (c *Cart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// GetItems returns all items in the cart
func (c *Cart) GetItems() []CartItem {
	result := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

// HasItem checks if an item exists in the cart
func (c *Cart) HasItem(sku string) bool {
	_, exists := c.items[sku]
	return exists
}

// GetQuantity returns the quantity of a specific item
func (c *Cart) GetQuantity(sku string) int {
	if item, exists := c.items[sku]; exists {
		return item.Quantity
	}
	return 0
}

// Subtotal returns the cart total before discounts
func (c *Cart) Subtotal() int64 {
	var total int64
	for _, item := range c.items {
		total += item.Price * int64(item.Quantity)
	}
	return total
}

// Total returns the cart total after discounts
func (c *Cart) Total() int64 {
	subtotal := c.Subtotal()
	if !c.hasDiscount {
		return subtotal
	}
	var discounted int64
	if c.discountType == DiscountPercent {
		discounted = subtotal - (subtotal * c.discountVal / 100)
	} else {
		discounted = subtotal - c.discountVal
	}
	if discounted < 0 {
		return 0
	}
	return discounted
}

// ApplyDiscount applies a discount to the cart
func (c *Cart) ApplyDiscount(code string, discountType DiscountType, value int64) {
	c.discountCode = code
	c.discountType = discountType
	c.discountVal = value
	c.hasDiscount = true
}

// RemoveDiscount removes any applied discount
func (c *Cart) RemoveDiscount() {
	c.hasDiscount = false
}

// DiscountAmount returns the savings from the applied discount
func (c *Cart) DiscountAmount() int64 {
	return c.Subtotal() - c.Total()
}
```

